		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}

	got := doJSON(t, router, http.MethodGet, "/vulnerabilities/CVE-2024-1001", nil)
	if got.Code != http.StatusOK {
		t.Fatalf("get status = %d", got.Code)
	}
